//! Generate Bazel lint flags from the authoritative Cargo lint policy.
use std::{
	fmt::Write,
	path::{Path, PathBuf},
};

use anyhow::{Context, Result, bail};
use clap::Parser;
use harvest_runtime::{JailedFs, MAX_FILE_BYTES};
use toml_edit::{DocumentMut, Item, TableLike};

const OUTPUT: &str = "bazel/clippy.bazelrc";
const HEADER: &str =
	"# Generated by cargo xtask clippy-config from [workspace.lints] in Cargo.toml.\n# Do not edit \
	 by hand; run `cargo xtask clippy-config` after changing the lint policy.\n# Applies only to \
	 crates that opt in via `[lints] workspace = true`.\n# The lint policy is authored against the \
	 rustup nightly, which may know\n# lints the pinned bazel toolchain predates; those names must \
	 not become\n# hard errors under the clippy aspect's -Dwarnings.\nbuild:clippy-strict \
	 --@rules_rust//rust/settings:clippy_flag=-Aunknown_lints\n";

#[derive(Parser)]
#[command(name = "cargo xtask clippy-config")]
struct Arguments {
	#[arg(long, default_value = ".")]
	workspace: PathBuf,
	#[arg(long)]
	check:     bool,
}

pub fn execute(arguments: Vec<String>) -> Result<()> {
	let Some(args) = crate::cli::arguments::<Arguments>("clippy-config", arguments)? else {
		return Ok(());
	};
	if update(&args.workspace, args.check)? {
		println!("Wrote {OUTPUT}.");
	} else {
		println!("{OUTPUT} is in sync with Cargo.toml.");
	}
	Ok(())
}

fn update(workspace: &Path, check: bool) -> Result<bool> {
	let fs = JailedFs::open(workspace)?;
	let manifest = fs.read(Path::new("Cargo.toml"), MAX_FILE_BYTES)?;
	let rendered = render(std::str::from_utf8(&manifest).context("Cargo.toml is not UTF-8")?)?;
	crate::generated::publish(
		&fs,
		Path::new(OUTPUT),
		rendered.as_bytes(),
		check,
		"cargo xtask clippy-config",
	)
}

fn render(manifest: &str) -> Result<String> {
	let document = manifest
		.parse::<DocumentMut>()
		.map_err(|_| anyhow::anyhow!("invalid Cargo.toml syntax"))?;
	let lints = document
		.get("workspace")
		.and_then(Item::as_table_like)
		.and_then(|table| table.get("lints"))
		.and_then(Item::as_table_like)
		.context("Cargo.toml has no workspace lint policy")?;
	let clippy = lints
		.get("clippy")
		.and_then(Item::as_table_like)
		.context("Cargo.toml has no workspace.lints.clippy table")?;
	let mut output = HEADER.to_owned();
	if let Some(rust) = lints.get("rust") {
		flags(
			&mut output,
			rust
				.as_table_like()
				.context("Rust lint policy must be a table")?,
			"",
		)?;
	}
	flags(&mut output, clippy, "clippy::")?;
	Ok(output)
}

fn flags(output: &mut String, table: &dyn TableLike, prefix: &str) -> Result<()> {
	let mut entries = Vec::new();
	for (name, entry) in table.iter() {
		if name.is_empty()
			|| !name
				.bytes()
				.all(|byte| byte.is_ascii_alphanumeric() || b"_-".contains(&byte))
		{
			bail!("lint names must contain only ASCII letters, digits, underscores or hyphens");
		}
		let (level, priority) = if let Some(level) = entry.as_str() {
			(level, 0)
		} else {
			let values = entry
				.as_table_like()
				.context("lint entries must be a level or table")?;
			let level = values
				.get("level")
				.and_then(Item::as_str)
				.context("lint table requires a string level")?;
			let priority = values
				.get("priority")
				.map(|value| {
					value
						.as_integer()
						.context("lint priority must be an integer")
				})
				.transpose()?
				.unwrap_or(0);
			(level, priority)
		};
		let flag = match level {
			"allow" => 'A',
			"warn" => 'W',
			"deny" => 'D',
			"forbid" => 'F',
			_ => bail!("unsupported lint level"),
		};
		entries.push((priority, name, flag));
	}
	entries.sort_unstable();
	for (_, name, flag) in entries {
		writeln!(
			output,
			"build:clippy-strict --@rules_rust//rust/settings:clippy_flag=-{flag}{prefix}{name}"
		)?;
		if output.len() > MAX_FILE_BYTES {
			bail!("generated lint policy exceeds its byte limit");
		}
	}
	Ok(())
}

#[cfg(test)]
mod tests {
	use super::*;
	const POLICY: &str = r#"
[workspace.lints.rust]
unsafe_code = { level = "forbid", priority = 1 }
unused = { level = "warn", priority = -2 }
unknown_lints = "deny"
[workspace.lints.clippy]
zeta = "allow"
all = { level = "warn", priority = -1 }
alpha = { level = "deny", priority = 0 }
[workspace.lints.clippy.pedantic]
level = "warn"
priority = -1
"#;
	#[test]
	fn generated_flags_preserve_rust_then_clippy_priority_and_override_precedence() -> Result<()> {
		let output = render(POLICY)?;
		let flags: Vec<_> = output
			.lines()
			.filter(|line| !line.starts_with('#'))
			.collect();
		assert_eq!(flags, [
			"build:clippy-strict --@rules_rust//rust/settings:clippy_flag=-Aunknown_lints",
			"build:clippy-strict --@rules_rust//rust/settings:clippy_flag=-Wunused",
			"build:clippy-strict --@rules_rust//rust/settings:clippy_flag=-Dunknown_lints",
			"build:clippy-strict --@rules_rust//rust/settings:clippy_flag=-Funsafe_code",
			"build:clippy-strict --@rules_rust//rust/settings:clippy_flag=-Wclippy::all",
			"build:clippy-strict --@rules_rust//rust/settings:clippy_flag=-Wclippy::pedantic",
			"build:clippy-strict --@rules_rust//rust/settings:clippy_flag=-Dclippy::alpha",
			"build:clippy-strict --@rules_rust//rust/settings:clippy_flag=-Aclippy::zeta",
		]);
		Ok(())
	}
	#[test]
	fn check_mode_refuses_missing_or_stale_output_without_creating_or_overwriting_it() -> Result<()>
	{
		let root = tempfile::tempdir()?;
		std::fs::write(root.path().join("Cargo.toml"), POLICY)?;
		assert!(update(root.path(), true).is_err());
		assert!(!root.path().join("bazel").exists());
		assert!(update(root.path(), false)?);
		assert!(!update(root.path(), true)?);
		std::fs::write(root.path().join(OUTPUT), b"stale config\n")?;
		assert!(update(root.path(), true).is_err());
		assert_eq!(std::fs::read(root.path().join(OUTPUT))?, b"stale config\n");
		Ok(())
	}
	#[test]
	fn malformed_policies_cannot_replace_an_existing_configuration() -> Result<()> {
		let root = tempfile::tempdir()?;
		std::fs::create_dir(root.path().join("bazel"))?;
		std::fs::write(root.path().join(OUTPUT), b"original\n")?;
		for policy in [
			"[workspace",                                                // Invalid TOML.
			"[workspace.lints.rust]\nunused='warn'",                     // Missing Clippy policy.
			"[workspace.lints.clippy]\nall='unexpected'",                // Invalid level.
			"[workspace.lints.clippy]\nall={level='warn',priority=1.5}", // Invalid rank.
			"[workspace.lints.clippy]\nall=false",                       // Invalid entry type.
			"[workspace.lints.clippy]\n\"all\\nbuild:injected\"='warn'", // Line injection.
		] {
			std::fs::write(root.path().join("Cargo.toml"), policy)?;
			assert!(update(root.path(), false).is_err());
			assert_eq!(std::fs::read(root.path().join(OUTPUT))?, b"original\n");
		}
		Ok(())
	}
	#[cfg(unix)]
	#[test]
	fn a_symlinked_output_parent_cannot_change_files_outside_the_workspace() -> Result<()> {
		let root = tempfile::tempdir()?;
		let outside = tempfile::tempdir()?;
		std::fs::write(root.path().join("Cargo.toml"), POLICY)?;
		std::fs::write(outside.path().join("clippy.bazelrc"), b"outside\n")?;
		std::os::unix::fs::symlink(outside.path(), root.path().join("bazel"))?;
		assert!(update(root.path(), false).is_err());
		assert_eq!(std::fs::read(outside.path().join("clippy.bazelrc"))?, b"outside\n");
		Ok(())
	}
}
